"""Furnish the loft mattress, matching the washed teal quilt and single faded-blue pillow in L1040628.
Standalone geometry/materials section after the mattress, using parent point/mesh/mat/room/bedbase.
"""
def _dress_loft_bed(point, mesh, mat, room, base, bounds):
    import base64, tempfile, math, bpy
    from pathlib import Path
    from math import cos,sin,exp,pi,tanh,sqrt
    def woven(label,token,basecol):
        m=mat(label,basecol,0,.93);nodes=m.node_tree.nodes;links=m.node_tree.links;b=nodes.get('Principled BSDF')
        b.inputs['Sheen Weight'].default_value=.14
        tmp=Path(tempfile.gettempdir())/'reindeer-quilt-packed';tmp.mkdir(exist_ok=True)
        for suffix in ('','-normal'):
            key='loft-'+token+suffix;f=tmp/(key+'.jpg');f.write_bytes(base64.b64decode(_LOFT_CLOTH_JPGS[key]));im=bpy.data.images.load(str(f),check_existing=False);im.name='Loft textiles | '+key;im.pack()
            if suffix:im.colorspace_settings.name='Non-Color'
            tex=nodes.new('ShaderNodeTexImage');tex.image=im
            if suffix:
                n=nodes.new('ShaderNodeNormalMap');n.inputs['Strength'].default_value=.53;links.new(tex.outputs['Color'],n.inputs['Color']);links.new(n.outputs['Normal'],b.inputs['Normal'])
            else:links.new(tex.outputs['Color'],b.inputs['Base Color'])
        return m
    quilt=woven('Loft quilt • washed teal matelassé','quilt','#709fa7')
    pc=woven('Loft pillow • faded periwinkle cotton','pillow','#889fc8')
    def grid_obj(name,verts,faces,uvs,m):
        ob=mesh(name,verts,faces,m,room)
        uv=ob.data.uv_layers.new(name='Woven repeat')
        for loop in ob.data.loops:uv.data[loop.index].uv=uvs[loop.vertex_index]
        ob.data.polygons.foreach_set('use_smooth',[True]*len(faces));return ob
    unit=.3048
    minx,maxx,miny,maxy=bounds
    L=(maxy-miny)*unit;W=(maxx-minx)*unit
    def world(x,y,z):return point(maxx-y/unit,miny+x/unit,base+z)
    # Include a little of the upper roll on the mattress. Additional cloth length falls over each outside edge.
    def over(a,m):
        if a<.017:return -1,.017-a
        if a>m-.017:return 1,a-m+.017
        return 0,0
    def cloth(u,v):
        sx,dx=over(u,L);sy,dy=over(v,W);ex=sx*dx;ey=sy*dy
        ed=sqrt(ex*ex+ey*ey);rad=.039
        if ed:
            mag=rad*(1-exp(-ed/rad)); drop=ed-mag
            bx=u-ex;by=v-ey
            # A flared triangular hand at each corner keeps fabric from collapsing to a vertical line.
            fold=(.0065*sin(31*u+12*v+.8)+.005*sin(19*v-8*u)+.005*sin(43*v-3*u))*(1-exp(-ed/.046))
            xx=bx+(mag+fold)*ex/ed; yy=by+(mag+fold)*ey/ed
        else:xx,yy=u,v;drop=0
        f1=.031*exp(-((v-(.57+.18*sin(u*2.15)+.28*u))/.058)**2)*exp(-((u-1.42)/.62)**2)
        f2=.020*exp(-((v-(1.07-.21*u+.08*sin(u*5)))/.045)**2)*exp(-((u-1.11)/.67)**2)
        soft=.006*sin(5*u+1.7*v)*sin(7*v-.45)+.004*sin(9*u+v)*cos(4.2*v)
        z=.186-drop+soft+f1+f2
        if ed:z=max(.007,z)
        return world(xx,yy,z)
    def sampled(a,b,n):return [a+(b-a)*i/n for i in range(n+1)]
    xx=sampled(-.112,.017,8)[:-1]+sampled(.017,L-.017,63)[:-1]+sampled(L-.017,L+.164,10)
    yy=sampled(-.156,.017,10)[:-1]+sampled(.017,W-.017,52)[:-1]+sampled(W-.017,W+.142,9)
    vs=[];fs=[];uvs=[]
    for j,v in enumerate(yy):
        for i,u in enumerate(xx):
            # Slight natural variations in the bottom hem length along the sides.
            if u<0:du=u*(1+.10*sin(10*v+.5))
            elif u>L:du=L+(u-L)*(1+.08*cos(9*v))
            else:du=u
            if v<0:dv=v*(1+.11*sin(9*u)+.04*sin(22*u))
            elif v>W:dv=W+(v-W)*(1+.07*cos(11*u))
            else:dv=v
            vs.append(cloth(du,dv));uvs.append((du/.18,dv/.18))
            if i and j:
                id=j*len(xx)+i;fs.append((id-len(xx)-1,id-len(xx),id,id-1))
    grid_obj('Loft | draped quilt, rippled cotton and bound edges',vs,fs,uvs,quilt)
    # Closed cotton sham with broad flattened flange, stitched corner ears and offset crown.
    ax=.227;ay=.34;cx=.336;cy=.79;ang=-.095;N=38;M=42;vs=[];uvs=[];fs=[]
    def pillowpos(p,q,upper):
        ap,aq=abs(p),abs(q);corner=ap*aq
        x=ax*p*(1-.065*aq**4);y=ay*q*(1-.067*ap**4)
        bound=min(1-ap,1-aq)
        puff=(1-exp(-(max(0,bound-.063)/.205)**1.53)) if bound>.063 else 0
        # Sloped crown and small tension pleats at both ends. Outer sham is loose and thin.
        dent=-.024*exp(-((p+.13)/.39)**2-((q-.21)/.40)**2)
        creases=.005*sin(26*p+4*q)*aq**4+.004*cos(21*q-3*p)*ap**6
        hem_z=.20+.024*(1-corner**2)+.012*sin(4*q+.2)*ap**3+.008*cos(5*p)*aq**3
        if upper:z=hem_z+.116*puff+dent*puff+.014*q*puff+creases
        else:z=hem_z-.038*puff+creases-.0035
        return world(cx+x*cos(ang)-y*sin(ang),cy+x*sin(ang)+y*cos(ang),z)
    for is_top in (0,1):
        start=len(vs)
        for j in range(M+1):
            q=(2*j/M-1)
            for i in range(N+1):
                p=2*i/N-1
                vs.append(pillowpos(p,q,is_top));uvs.append(((p+1)*1.7,(q+1)*2.6))
                if i and j:
                    idx=start+j*(N+1)+i;f=(idx-N-2,idx-N-1,idx,idx-1);fs.append(f if is_top else tuple(reversed(f)))
    perim=[i for i in range(N+1)]+[j*(N+1)+N for j in range(1,M+1)]+[M*(N+1)+i for i in range(N-1,-1,-1)]+[j*(N+1) for j in range(M-1,0,-1)]
    n=(N+1)*(M+1)
    for k,i in enumerate(perim):
        j=perim[(k+1)%len(perim)];fs.append((i,j,j+n,i+n))
    grid_obj('Loft | relaxed pale-blue flanged pillow',vs,fs,uvs,pc)

_LOFT_CLOTH_JPGS = {
'loft-pillow':'',
'loft-pillow-normal':'',
'loft-quilt':'',
'loft-quilt-normal':'',
}
_dress_loft_bed(point, mesh, mat, room, bedbase, loft_bed_bounds)
